import { i18n } from 'i18n';

import { TRANSFORM_LOCALE } from './transformLocale';

export const formatDate = (
	date: Date | null,
	format: 'short' | 'medium' | 'long' | 'json' = 'short',
	filter: 'from' | 'to' = 'from',
) => {
	if (!date) {
		return null;
	}

	switch (format) {
		case 'short':
			return date.toLocaleString(TRANSFORM_LOCALE[i18n.language], {
				month: '2-digit',
				day: '2-digit',
				year: 'numeric',
			});

		case 'medium':
			return date.toLocaleString(TRANSFORM_LOCALE[i18n.language], {
				month: '2-digit',
				day: '2-digit',
				year: 'numeric',
				hour: '2-digit',
				minute: '2-digit',
			});

		case 'long':
			return date.toLocaleString(TRANSFORM_LOCALE[i18n.language], {
				month: 'short',
				day: 'numeric',
				hour: '2-digit',
				minute: '2-digit',
				second: '2-digit',
			});

		case 'json':
			if (filter === 'to') {
				date.setDate(date.getDate() + 1);
				date.setMilliseconds(date.getMilliseconds() - 1);
			}

			return date.toJSON();

		default:
			return null;
	}
};
